typedef float rational_t;

class geometry_manager {
public:
  void rebuild_view_frame();
};

class hw_rasta {
public:
  void set_fog_dist(float start_dist, float end_dist);
};

extern geometry_manager *geometry_manager_instance __asm__("_16geometry_manager$instance");
extern hw_rasta *hw_rasta_instance __asm__("_8hw_rasta$instance");
extern rational_t PROJ_FAR_PLANE_D;
extern rational_t g_debug_fog_override;

class fog_manager {
  char padding[0x14];
  rational_t specified_fog_start_distance;
  rational_t specified_fog_end_distance;
  rational_t specified_fog_table_gamma;
  rational_t computed_fog_start_distance;
  rational_t computed_fog_end_distance;
  rational_t fog_of_war;
public:
  void update_fog(bool forced);
};

const rational_t MIN_FOG_END_DIST = 20;

void fog_manager::update_fog(bool forced)
{
  float last_computed_fog_end_distance = computed_fog_end_distance;
  if ( fog_of_war > 0 )
  {
    rational_t r = 1.0f - (0.5f * fog_of_war);
    computed_fog_start_distance = specified_fog_start_distance * r;
    if ( specified_fog_end_distance > MIN_FOG_END_DIST )
    {
      if ( specified_fog_end_distance*r < MIN_FOG_END_DIST )
        computed_fog_end_distance = MIN_FOG_END_DIST;
      else
        computed_fog_end_distance = specified_fog_end_distance * r;
    }
    else
      computed_fog_end_distance = specified_fog_end_distance;
  }
  else
  {
    computed_fog_start_distance = specified_fog_start_distance;
    computed_fog_end_distance = specified_fog_end_distance;
  }

  if( last_computed_fog_end_distance != computed_fog_end_distance || forced)
  {
    if( g_debug_fog_override )
      PROJ_FAR_PLANE_D = g_debug_fog_override;
    else
      PROJ_FAR_PLANE_D = computed_fog_end_distance;

    geometry_manager_instance->rebuild_view_frame();
    hw_rasta_instance->set_fog_dist( computed_fog_start_distance, computed_fog_end_distance );
  }
}
